function setTimestamp(row, col, value) {
  if (value === undefined) return;
  if (value === null) { row[col] = null; return; }
  if (typeof value === 'string' && ISO_TZ_RE.test(value)) { row[col] = value; return; }

  let d = null;
  if (typeof value === 'number') {
    if (!isFinite(value)) return;
    d = new Date(value * 1000);
  } else if (typeof value === 'string') {
    d = new Date(value);
  } else {
    return;
  }

  if (d && !isNaN(d.getTime())) {
    row[col] = d.toISOString();
  } else {
    row[col + '_text'] = typeof value === 'string' ? value : String(value);
  }
}
